// ==================== 工具函数 ====================

function genId(): string {
  return 'po_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

function formatDate(date: string | Date): string {
  const d = typeof date === 'string' ? new Date(date) : date;
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  const h = String(d.getHours()).padStart(2, '0');
  const min = String(d.getMinutes()).padStart(2, '0');
  return `${y}-${m}-${day} ${h}:${min}`;
}

function getStatusMeta(status: OrderStatus) {
  return ORDER_STATUS.find((s) => s.key === status) || ORDER_STATUS[0];
}

function getStatusIndex(status: OrderStatus): number {
  return ORDER_STATUS.findIndex((s) => s.key === status);
}

function nextStatus(current: OrderStatus): OrderStatus | null {
  const idx = getStatusIndex(current);
  if (idx < 0 || idx >= ORDER_STATUS.length - 2) return null; // 排除异常
  return ORDER_STATUS[idx + 1].key;
}

// ==================== 物流查询（17track 真实接口 + Mock 降级） ====================

const DEFAULT_17TRACK_KEY = 'BB51C787D092993CBA780AE40FA42BE5';

async function queryLogistics(
  trackingNumber: string,
  config: LogisticsConfig,
): Promise<LogisticsQueryResult> {
  if (!trackingNumber || trackingNumber.trim().length < 5) {
    return {
      success: false,
      status: null,
      traces: [],
      errorMsg: '运单号太短或无效',
    };
  }

  // 未配置密钥 → 使用模拟数据
  if (config.provider === 'none' || !isConfigValid(config)) {
    return mockQueryLogistics(trackingNumber);
  }

  // 17track 真实接口调用
  try {
    const apiKey = config.apiKey || DEFAULT_17TRACK_KEY;
    const result = await query17Track(trackingNumber, apiKey);
    return result;
  } catch (err) {
    logger.error('17track 物流查询失败:', String(err));
    // 查询失败时降级到 mock
    return mockQueryLogistics(trackingNumber);
  }
}

function isConfigValid(config: LogisticsConfig): boolean {
  if (config.provider === '17track') {
    return !!(config.apiKey && config.apiKey.trim().length > 0);
  }
  return false;
}

// 17track 状态码 → 本地状态映射
// https://www.17track.net/en/api-doc#states
function map17TrackStatus(status: number): OrderStatus {
  switch (status) {
    case 1: // 已揽收/已发货
      return 'shipped';
    case 2: // 运输中
    case 3: // 到达待取
    case 10: // 到达投递局
      return 'in_transit';
    case 4: // 已签收/成功投递
      return 'arrived';
    case 5: // 投递失败
    case 6: // 退回
    case 7: // 异常
    case 12: // 滞留件
    case 13: // 销毁
      return 'abnormal';
    case 0: // 查询不到 / 无信息
    case 8: // 运输过久
    case 9: // 可能异常
    case 11: // 已签收（但可能是代收）
    default:
      return 'in_transit';
  }
}

function format17TrackTime(t: string): string {
  // 17track 返回的时间格式通常为 "2024-01-15 10:30"
  if (!t) return '';
  // 如果已经是 YYYY-MM-DD HH:mm 格式直接返回
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}/.test(t)) return t;
  const d = new Date(t);
  if (!isNaN(d.getTime())) return formatDate(d);
  return t;
}

async function query17Track(
  trackingNumber: string,
  apiKey: string,
): Promise<LogisticsQueryResult> {
  // 第一步：注册单号
  const registerBody = {
    tracking_numbers: [
      {
        number: trackingNumber.trim(),
      },
    ],
  };

  try {
    const registerRes = await fetch('https://api.17track.net/track/v2.2/register', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify(registerBody),
    });

    if (!registerRes.ok) {
      logger.warn(`17track register HTTP ${registerRes.status}`);
    }
    // 注册失败不阻塞查询，继续调 track 接口
  } catch (err) {
    logger.warn('17track register 调用异常（继续查询）:', String(err));
  }

  // 第二步：查询轨迹
  const trackBody = {
    tracking_numbers: [
      {
        number: trackingNumber.trim(),
      },
    ],
  };

  const trackRes = await fetch('https://api.17track.net/track/v2.2/track', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify(trackBody),
  });

  if (!trackRes.ok) {
    throw new Error(`17track track HTTP ${trackRes.status}`);
  }

  const data = await trackRes.json();

  // 解析返回结构
  // accepted: [{ number, carrier, status, track_info: { events: [{ time, location, desc }] } }]
  // rejected: [{ number, ... }]
  const accepted = data?.accepted || [];
  const rejected = data?.rejected || [];

  if (rejected && rejected.length > 0) {
    const reason = rejected[0]?.error?.message || '单号无法识别或不支持该快递商';
    throw new Error(reason);
  }

  if (!accepted || accepted.length === 0) {
    throw new Error('未查询到物流信息');
  }

  const item = accepted[0];
  const statusCode = item.status || 0;
  const carrier = item.carrier || '';
  const events = item?.track_info?.event || [];

  // 轨迹按时间倒序（最新在前），我们转为正序（最旧在前）展示时间轴
  const traces: LogisticsTrace[] = [...events]
    .sort((a: { time: string }, b: { time: string }) => {
      const ta = new Date(a.time).getTime();
      const tb = new Date(b.time).getTime();
      return tb - ta; // 最新在前
    })
    .map((e: { time: string; location: string; desc: string }) => ({
      time: format17TrackTime(e.time),
      location: e.location || '',
      desc: e.desc || '',
    }));

  const latestTime = traces.length > 0 ? traces[0].time : undefined;
  const mappedStatus = map17TrackStatus(statusCode);
  // 状态描述补充：如果 carrier 里有名称，拼到一起
  const carrierName = item?.carrier_name?.['zh-CN'] || carrier || '未知快递';

  return {
    success: true,
    status: mappedStatus,
    carrier: carrierName,
    latestTime,
    traces,
  };
}

