// ==================== 统计计算 ====================

function computeStats(orders: PurchaseOrder[]) {
  const stats = {
    total: orders.length,
    inTransit: 0,
    arrived: 0,
    warehoused: 0,
    abnormal: 0,
    ordered: 0,
    pendingShip: 0,
    shipped: 0,
  };
  orders.forEach((o) => {
    if (o.status === 'in_transit') stats.inTransit++;
    if (o.status === 'arrived') stats.arrived++;
    if (o.status === 'warehoused') stats.warehoused++;
    if (o.status === 'abnormal') stats.abnormal++;
    if (o.status === 'ordered') stats.ordered++;
    if (o.status === 'pending_ship') stats.pendingShip++;
    if (o.status === 'shipped') stats.shipped++;
  });
  return stats;
}

// ==================== 异常记录检测 ====================

type AbnormalType = 'shipping_delay' | 'arrival_damaged' | 'arrival_defective' | 'quantity_missing';

interface AbnormalRecord {
  type: AbnormalType;
  order: PurchaseOrder;
  triggerInfo: string;
  suggestion: string;
}

const ABNORMAL_TYPE_META: Record<AbnormalType, { label: string; color: string; icon: typeof AlertTriangle }> = {
  shipping_delay: { label: '运输超7天', color: 'text-amber-600', icon: CalendarClock },
  arrival_damaged: { label: '到库破损', color: 'text-red-600', icon: PackageOpen },
  arrival_defective: { label: '到库瑕疵', color: 'text-orange-600', icon: AlertCircle },
  quantity_missing: { label: '数量漏件', color: 'text-purple-600', icon: PackageMinus },
};

const ABNORMAL_SUGGESTIONS: Record<AbnormalType, string> = {
  shipping_delay:
    '建议联系货代/物流查询包裹并催件；若物流信息长期停滞，按货代规则申请查件、理赔或补发。',
  arrival_damaged:
    '建议第一时间拍照留证，联系卖家/货代申请破损理赔或补发，破损严重可拒收。',
  arrival_defective:
    '评估瑕疵是否影响销售，影响则联系卖家协商换货、退款或降级处理。',
  quantity_missing:
    '建议实际清点核对到货数量与采购数量，差额拍照留证，联系卖家/货代申请补发或退款。',
};

// 从 expressTimeline 文本中解析预计天数（如「预计3天」「5-7天」）
function extractExpectedDays(text: string): number | null {
  const match = text.match(/(\d+)\s*天/);
  if (match) return parseInt(match[1], 10);
  const rangeMatch = text.match(/(\d+)\s*[-~～]\s*(\d+)\s*天/);
  if (rangeMatch) return parseInt(rangeMatch[2], 10);
  return null;
}

// 获取运输已过天数：优先用 shippedAt，其次用 updatedAt 作为发货时间近似
function getShippingDays(order: PurchaseOrder): number | null {
  const baseTime = order.shippedAt || order.updatedAt || order.createdAt;
  if (!baseTime) return null;
  const start = new Date(baseTime).getTime();
  const now = Date.now();
  const diffDays = (now - start) / (1000 * 60 * 60 * 24);
  return Math.floor(diffDays);
}

function detectAbnormalRecords(orders: PurchaseOrder[]): AbnormalRecord[] {
  const results: AbnormalRecord[] = [];
  const arrivedOrWarehoused = (s: OrderStatus) => s === 'arrived' || s === 'warehoused';
  const notArrived = (s: OrderStatus) =>
    s === 'shipped' || s === 'in_transit' || s === 'pending_ship' || s === 'ordered';

  orders.forEach((order) => {
    // 1. 运输超 7 天：已发货/运输中 且超过 7 天（或预计时效 > 7 天）
    if (order.status === 'shipped' || order.status === 'in_transit') {
      const days = getShippingDays(order);
      const expectedDays = order.expressTimeline
        ? extractExpectedDays(order.expressTimeline)
        : null;
      const isOverdue = (days !== null && days > 7) || (expectedDays !== null && expectedDays > 7);
      if (isOverdue) {
        const info =
          days !== null
            ? `已运输 ${days} 天`
            : `预计时效 ${expectedDays} 天`;
        results.push({
          type: 'shipping_delay',
          order,
          triggerInfo: info,
          suggestion: ABNORMAL_SUGGESTIONS.shipping_delay,
        });
      }
    }

    // 2. 到库破损
    if (arrivedOrWarehoused(order.status) && order.arrivalQuality === 'damaged') {
      results.push({
        type: 'arrival_damaged',
        order,
        triggerInfo: '到货质检：破损',
        suggestion: ABNORMAL_SUGGESTIONS.arrival_damaged,
      });
    }

    // 3. 到库瑕疵
    if (arrivedOrWarehoused(order.status) && order.arrivalQuality === 'defective') {
      results.push({
        type: 'arrival_defective',
        order,
        triggerInfo: '到货质检：瑕疵',
        suggestion: ABNORMAL_SUGGESTIONS.arrival_defective,
      });
    }

    // 4. 数量漏件
    if (arrivedOrWarehoused(order.status) && order.arrivalQuality === 'missing') {
      results.push({
        type: 'quantity_missing',
        order,
        triggerInfo: '到货质检：漏件',
        suggestion: ABNORMAL_SUGGESTIONS.quantity_missing,
      });
    }

    // 未用到 notArrived，保留变量名避免未使用告警
    void notArrived;
  });

  return results;
}

function computeAbnormalStats(records: AbnormalRecord[]) {
  return {
    total: records.length,
    shippingDelay: records.filter((r) => r.type === 'shipping_delay').length,
    damaged: records.filter((r) => r.type === 'arrival_damaged').length,
    defective: records.filter((r) => r.type === 'arrival_defective').length,
    missing: records.filter((r) => r.type === 'quantity_missing').length,
  };
}

